import {mountBuildingPreviewPaint} from './building-preview-paint.js?v=keyboard-cursor-1';
import {BUILDING_DETAILS} from './building-surface-details.js?v=keyboard-cursor-1';
import {BUILDING_MATERIALS} from './building-materials.js?v=keyboard-cursor-1';
import {mountBuildingPreviewCamera} from './building-preview-camera.js?v=keyboard-cursor-1';
import {drawBuildingPlaneGuide} from './building-plane-guide.js?v=keyboard-cursor-1';
import {buildingSlot,parseBuildingSlot,sameBuildingFootprint} from './building-footprints.js?v=keyboard-cursor-1';
import {mountBuildingBlockEditor} from './building-block-editor.js?v=keyboard-cursor-1';
import {REPLACEABLE_STYLES} from './building-art.js?v=keyboard-cursor-1';
import {defaultBuildingDesign,validateBuildingDesign,applyBuildingDesign,exportBuildingDesign,importBuildingDesign,drawBuildingDesign} from './building-designs.js?v=keyboard-cursor-1';
export function showBuildingDesigner({city,dialog,apply,close},initialSource=2){
 const $=id=>document.getElementById(id);const initial=parseBuildingSlot(initialSource);let source=initial.source,footprint=initial.footprint,rotation=0;const slot=()=>buildingSlot(source,footprint);let draft=structuredClone(city.buildingDesigns?.[slot()]||defaultBuildingDesign(slot()));
 dialog('Building designer',`<p>Create a building model and apply it to a residential, commercial or non-farm industrial style. You can design before your city has that building; the model appears when that style develops. This changes appearance, with the existing lot’s population, jobs and costs.</p><div class="building-designer"><div><canvas id="designPreview" width="256" height="384" tabindex="0" aria-label="Custom building preview. Drag to pan, scroll or use plus and minus to zoom, arrow keys to pan, Home to reset."></canvas><div class="design-view-controls"><button id="designZoomOut" aria-label="Zoom out building preview">−</button><output id="designZoom">100%</output><button id="designZoomIn" aria-label="Zoom in building preview">+</button><button id="designResetView">Reset view</button></div><div class="design-view-controls"><button id="rotateBackDesign" aria-label="Rotate building preview counterclockwise">↶</button><button id="rotateDesign">Rotate preview · North</button></div><p class="fine">Pan: drag the model · Scroll to zoom · Home resets the view.</p></div><div><label>Preview tool<select id="previewTool"><option value="pan">Pan camera</option><option value="paint">Paint visible surfaces</option><option value="fill">Fill connected surface</option><option value="detail">Place building details</option><option value="sample">Sample surface material</option></select></label><label>Building detail<select id="previewDetail" disabled>${BUILDING_DETAILS.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Paint area<select id="previewPaintScope"><option value="floor">Individual floor surface</option><option value="column">Whole column side</option></select></label><label>Preview material<select id="previewMaterial">${BUILDING_MATERIALS.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><p class="fine">Details: place a window, door, vent or ledge over the paint; choose Remove detail to erase it. Fill: click a connected wall or roof area of the same material. Paint: drag then release; Shift on release or Escape cancels. Arrows move the paint cursor; Enter paints or samples. Scroll zooms; Home resets. Use the layout or layered Undo button to undo paint.</p><p id="previewPaintStatus" role="status"></p><label>Replace building style<select id="designSource">${Object.entries(REPLACEABLE_STYLES).map(([key,v])=>`<option value="${key}" ${Number(key)===source?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Tile footprint<select id="designFootprint">${Array.from({length:16},(_,i)=>{const w=i%4+1,h=Math.floor(i/4)+1;return `<option value="${w}x${h}" ${w===footprint.width&&h===footprint.height?'selected':''}>${w} × ${h} tiles</option>`;}).join('')}</select></label><label>Design name<input id="designName" maxlength="40"></label><label>Floors (1–24)<input id="designFloors" type="number" min="1" max="24" step="1"></label><label>Width (6–10)<input id="designWidth" type="range" min="6" max="10" step="1"></label><label>Depth (6–10)<input id="designDepth" type="range" min="6" max="10" step="1"></label><label>Roof<select id="designRoof"><option value="flat">Flat</option><option value="step">Stepped upper floors</option><option value="spire">Spire</option></select></label><div class="actions"><label>Facade<input id="designFacade" type="color"></label><label>Windows<input id="designWindows" type="color"></label><label>Accents<input id="designAccent" type="color"></label></div><div id="buildingBlockEditor"></div><p id="designStatus" role="status"></p><div class="actions"><button id="applyDesign" class="primary">Apply to city</button><button id="removeDesign">Use original artwork</button><button id="exportDesign">Export building file</button><button id="importDesign">Import building file</button><input id="designFile" type="file" accept=".json,application/json" hidden><button id="closeDesign">Close</button></div><p class="fine">One custom model per style and tile footprint, saved with this city. Natural growth currently creates 1×1, 2×2 and 3×3 buildings; other footprints can be designed for matching imported cities. Imported files open as a draft until applied. Building files use SIMS3000’s own compact model format; original game building files are not supported. Independent layers support overhangs on a 10×10×24 block grid; cubes and wedges are available, with four wedge orientations. The full fourteen-block palette is not yet implemented.</p></div></div>`);
 let blockEditor,previewCamera,previewPaint;const canvas=$('designPreview'),fields={name:'designName',floors:'designFloors',width:'designWidth',depth:'designDepth',roof:'designRoof',facade:'designFacade',windows:'designWindows',accent:'designAccent'};
 function render(){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,384);const camera=previewCamera?.state||{zoom:1,x:0,y:0};ctx.save();ctx.translate(camera.x,camera.y);ctx.scale(camera.zoom,camera.zoom);drawBuildingDesign(ctx,draft,rotation);if(blockEditor?.selection())drawBuildingPlaneGuide(ctx,draft,blockEditor.selection(),rotation);previewPaint?.draw(ctx);ctx.restore();$('rotateDesign').textContent='Rotate preview · '+['North','East','South','West'][rotation];$('removeDesign').disabled=!city.buildingDesigns?.[slot()];}
 function fill(){previewPaint?.reset();previewCamera?.reset();for(const [key,id]of Object.entries(fields))$(id).value=draft[key];blockEditor?.reset();render();}
 function read(){return validateBuildingDesign({...Object.fromEntries(Object.entries(fields).map(([key,id])=>[key,['floors','width','depth'].includes(key)?Number($(id).value):$(id).value])),...(draft.footprint?{footprint:draft.footprint}:{}),...(draft.voxels?{voxels:draft.voxels,...(draft.blockGeometry?{blockGeometry:draft.blockGeometry}:{}),...(draft.surfaceDetails?{surfaceDetails:draft.surfaceDetails}:{}),...(draft.surfacePaint?{surfacePaint:draft.surfacePaint}:{}),...(draft.materials?{materials:draft.materials}:{})}:draft.blocks?{blocks:draft.blocks,...(draft.surfaceDetails?{surfaceDetails:draft.surfaceDetails}:{}),...(draft.surfacePaint?{surfacePaint:draft.surfacePaint}:{}),...(draft.materials?{materials:draft.materials}:{})}:{})});}
 for(const id of Object.values(fields))$(id).oninput=()=>{try{draft=read();$('designStatus').textContent='Preview only · apply when ready.';render();}catch(e){$('designStatus').textContent=e.message;}};
 $('rotateDesign').onclick=()=>{rotation=(rotation+1)%4;render();};$('rotateBackDesign').onclick=()=>{rotation=(rotation+3)%4;render();};function selectSlot(){source=Number($('designSource').value);const [width,height]=$('designFootprint').value.split('x').map(Number);footprint={width,height};draft=structuredClone(city.buildingDesigns?.[slot()]||defaultBuildingDesign(slot()));fill();$('designStatus').textContent='Loaded this style and footprint’s saved model, or a fresh draft.';}$('designSource').onchange=selectSlot;$('designFootprint').onchange=selectSlot;
 $('applyDesign').onclick=()=>{try{draft=read();applyBuildingDesign(city,slot(),draft);apply();render();$('designStatus').textContent='Applied to this city. Current and future buildings of the selected style and footprint use this model.';}catch(e){$('designStatus').textContent=e.message;}};
 $('removeDesign').onclick=()=>{delete city.buildingDesigns[slot()];delete city.buildingReplacements[slot()];apply();render();$('designStatus').textContent='Original artwork restored for this style.';};
 $('exportDesign').onclick=()=>{try{const data=exportBuildingDesign(read()),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sims3000-building.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('designStatus').textContent='Building file exported.';}catch(e){$('designStatus').textContent=e.message;}};
 $('importDesign').onclick=()=>$('designFile').click();$('designFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>32768)throw Error('Building files must be smaller than 32 KB.');const imported=importBuildingDesign(await file.text());if(!document.contains(canvas))return;if(!sameBuildingFootprint(imported.footprint,footprint))throw Error('This file has a different tile footprint. Select its footprint before importing.');draft=imported;fill();$('designStatus').textContent='Imported as a draft. Apply to city when ready.';}catch(e){if(document.contains(canvas))$('designStatus').textContent=e.message;}finally{event.target.value='';}};
 previewCamera=mountBuildingPreviewCamera(canvas,{zoomIn:$('designZoomIn'),zoomOut:$('designZoomOut'),reset:$('designResetView'),label:$('designZoom')},render);
 blockEditor=mountBuildingBlockEditor($('buildingBlockEditor'),{get:()=>draft,view:render,set:next=>{draft=next;render();$('designStatus').textContent='Preview only · apply when ready.';}});previewPaint=mountBuildingPreviewPaint(canvas,{get:()=>({...draft,rotation}),camera:()=>previewCamera.state,apply:materials=>blockEditor.applyMaterials(materials),applyFloor:paint=>blockEditor.applyFloorPaint(paint),applyDetails:details=>blockEditor.applyDetails(details),detail:$('previewDetail'),scope:$('previewPaintScope'),render,mode:$('previewTool'),material:$('previewMaterial'),status:$('previewPaintStatus')});$('closeDesign').onclick=close;fill();
}
